def quicksort(arr):
    """Return a new sorted list using quicksort."""
    if len(arr) <= 1:
        return arr
    pivot_value = arr[len(arr) // 2]
    less_than_pivot = [x for x in arr if x < pivot_value]
    equal_to_pivot = [x for x in arr if x == pivot_value]
    greater_than_pivot = [x for x in arr if x > pivot_value]
    return quicksort(less_than_pivot) + equal_to_pivot + quicksort(greater_than_pivot)


print(quicksort([3, 6, 8, 10, 1, 2, 1]))  # [1, 1, 2, 3, 6, 8, 10]

