def quicksort(arr):
    """Return a new sorted list using quicksort with three-way partitioning."""
    if len(arr) <= 1:
        return arr

    def partition(low, high):
        if low >= high:
            return

        lt, gt = low, high
        i = low
        pivot = arr[high]

        while i <= gt:
            if arr[i] < pivot:
                arr[lt], arr[i] = arr[i], arr[lt]
                lt += 1
                i += 1
            elif arr[i] > pivot:
                arr[gt], arr[i] = arr[i], arr[gt]
                gt -= 1
            else:
                i += 1

        partition(low, lt - 1)
        partition(gt + 1, high)

    partition(0, len(arr) - 1)
    return arr

